    summary = 'Sydney: the Opera House on the harbour, golden beaches and the Blue Mountains a train ride away.',
    history = 'Aboriginal people have lived in the Sydney area for at least 40,000 years. British colonisation began at Sydney Cove in 1788.',
    culture = 'Beach and outdoor life, café culture, and growing recognition of the world''s oldest living cultures.',
    beliefs = 'Christianity is the largest faith, but almost 40% of Australians report no religion.',
    etiquette = 'Swim between the red and yellow flags; beaches have strong rip currents. Wear sunscreen even on cloudy days.',
    cost_index = 4,
    price_meal = 25,
    price_coffee = 5,
    price_hotel_night = 220,
    price_local_transport = 4,
    emergency_police = '000',
    emergency_ambulance = '000',
    emergency_fire = '000',
    tourist_police = NULL,
