-- Cities ---------------------------------------------------------------
INSERT INTO rj_cities (country_id, name_en, name_th, lat, lng, environment, cost_index, best_season, summary, history)
VALUES ((SELECT id FROM rj_countries WHERE iso2 = 'TH'), 'Bangkok', 'กรุงเทพมหานคร', 13.7563, 100.5018, 'urban', NULL, 'November to February', 'Thailand''s buzzing capital: royal palaces and riverside temples, giant markets, rooftop views and street food on every corner.', 'Founded as the royal capital in 1782 by King Rama I on the east bank of the Chao Phraya River, Bangkok grew from a fortified island, Rattanakosin, into a megacity of over 10 million people.')
