    cost_index = new.cost_index, best_season = new.best_season, summary = new.summary, history = new.history;
INSERT INTO rj_cities (country_id, name_en, name_th, lat, lng, environment, cost_index, best_season, summary, history)
VALUES ((SELECT id FROM rj_countries WHERE iso2 = 'TH'), 'Chiang Mai', 'เชียงใหม่', 18.7883, 98.9853, 'mixed', 2, 'November to February', 'The laid-back capital of the north, with a moated old city full of temples and the country''s highest mountains an hour away.', 'Founded in 1296 by King Mangrai as the capital of the Lanna Kingdom, which kept its own language, script and art until it became part of Siam in the 19th century.')
AS new ON DUPLICATE KEY UPDATE name_th = new.name_th, lat = new.lat, lng = new.lng, environment = new.environment,
    cost_index = new.cost_index, best_season = new.best_season, summary = new.summary, history = new.history;
INSERT INTO rj_cities (country_id, name_en, name_th, lat, lng, environment, cost_index, best_season, summary, history)
VALUES ((SELECT id FROM rj_countries WHERE iso2 = 'TH'), 'Krabi', 'กระบี่', 8.0863, 98.9063, 'nature', 2, 'November to April', 'Limestone cliffs rising out of turquoise water, island-hopping boat trips and beaches on the Andaman Sea.', 'Prehistoric cave paintings show people lived here for thousands of years. Krabi was a quiet fishing province until tourism took off in the 1980s and 1990s.')
