SELECT (SELECT id FROM rj_cities WHERE name_en = 'Bangkok'), (SELECT id FROM rj_categories WHERE slug = 'attraction'), 'Wat Pho', 'วัดโพธิ์', 'Home of the 46 m Reclining Buddha and the birthplace of traditional Thai massage.', 'One of Bangkok''s oldest temples, with over 1,000 Buddha images. Its massage school offers treatments in the temple grounds.', 'Rebuilt by King Rama I and expanded by Rama III, who turned it into Thailand''s first public centre of learning.', NULL, 'MRT Sanam Chai station, exit 1, then a 5-minute walk.', NULL, 13.7465, 100.493, 1, 300, 300, 'urban', 'city', 1, NULL, 1.5, 0, NULL, '08:00–18:30 daily', 'Shoulders and knees covered; remove shoes inside buildings', 'published'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM rj_places WHERE name_en = 'Wat Pho' AND city_id = (SELECT id FROM rj_cities WHERE name_en = 'Bangkok'));
