SELECT (SELECT id FROM rj_cities WHERE name_en = 'Bangkok'), (SELECT id FROM rj_categories WHERE slug = 'market'), 'Chatuchak Weekend Market', 'ตลาดนัดจตุจักร', 'More than 15,000 stalls selling clothes, crafts, plants, antiques and street food.', 'One of the world''s biggest weekend markets. Come early before the heat and grab a map at the entrance.', NULL, NULL, 'MRT Kamphaeng Phet or BTS Mo Chit.', NULL, 13.7999, 100.5503, 1, NULL, NULL, 'urban', 'city', 0, NULL, 3, 0, NULL, 'Saturday–Sunday 09:00–18:00', NULL, 'published'
