INSERT INTO rj_places (city_id, category_id, name_en, name_th, summary, description, history, culture_beliefs, how_to_get_there, address, lat, lng, price_level, price_min, price_max, environment, terrain, is_historical, difficulty, duration_hours, permit_required, permit_info, opening_hours, dress_code, status)
SELECT (SELECT id FROM rj_cities WHERE name_en = 'Sydney'), (SELECT id FROM rj_categories WHERE slug = 'attraction'), 'Taronga Zoo', 'สวนสัตว์ทารองกา', 'Australian animals with harbour views, a short ferry ride from Circular Quay.', 'Take the cable car up from the wharf.', NULL, NULL, NULL, NULL, -33.8436, 151.2412, 3, 50, 60, 'nature', 'sea', 0, NULL, 4, 0, NULL, NULL, NULL, 'published'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM rj_places WHERE name_en = 'Taronga Zoo' AND city_id = (SELECT id FROM rj_cities WHERE name_en = 'Sydney'));
INSERT IGNORE INTO rj_place_tags (place_id, tag_id)
SELECT (SELECT id FROM rj_places WHERE name_en = 'Taronga Zoo' LIMIT 1), id FROM rj_tags WHERE slug IN ('family', 'viewpoint');
INSERT INTO rj_places (city_id, category_id, name_en, name_th, summary, description, history, culture_beliefs, how_to_get_there, address, lat, lng, price_level, price_min, price_max, environment, terrain, is_historical, difficulty, duration_hours, permit_required, permit_info, opening_hours, dress_code, status)
SELECT (SELECT id FROM rj_cities WHERE name_en = 'Sydney'), (SELECT id FROM rj_categories WHERE slug = 'bar'), 'Opera Bar', 'โอเปร่าบาร์', 'Outdoor tables under the Opera House facing the Harbour Bridge.', 'Best at sunset.', NULL, NULL, NULL, NULL, -33.8578, 151.2115, 2, 12, 25, 'urban', 'sea', 0, NULL, NULL, 0, NULL, NULL, NULL, 'published'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM rj_places WHERE name_en = 'Opera Bar' AND city_id = (SELECT id FROM rj_cities WHERE name_en = 'Sydney'));
INSERT IGNORE INTO rj_place_tags (place_id, tag_id)
SELECT (SELECT id FROM rj_places WHERE name_en = 'Opera Bar' LIMIT 1), id FROM rj_tags WHERE slug IN ('viewpoint', 'night_view', 'relax');

