UPDATE rj_places SET best_time = COALESCE(best_time, 'Afternoon tea in the Authors'' Lounge'), tips = COALESCE(tips, 'Even if you don''t stay, the riverside terrace is open for drinks.') WHERE name_en = 'Mandarin Oriental, Bangkok';
UPDATE rj_places SET best_time = COALESCE(best_time, 'Weekday morning'), tips = COALESCE(tips, 'Visits are by guided tour only; the tour starts every 20–30 minutes.') WHERE name_en = 'Jim Thompson House';
