UPDATE rj_places SET best_time = COALESCE(best_time, 'Late afternoon, for sunset from the rooftop'), tips = COALESCE(tips, 'The rooftop terrace has free views of Doi Suthep.') WHERE name_en = 'Maya Lifestyle Shopping Center';
