UPDATE rj_places SET best_time = COALESCE(best_time, 'Morning, 07:00–10:00'), tips = COALESCE(tips, 'Many shops close by early afternoon and on Wednesdays and Sundays.') WHERE name_en = 'Tsukiji Outer Market';
