INSERT INTO rj_risk_scores (country_id, city_id, risk_type, score, description, how_to_handle, source_url)
SELECT (SELECT id FROM rj_countries WHERE iso2 = 'TH'), NULL, 'crime_petty', 3, 'Common tourist scams: "the palace is closed today", gem-shop detours, rigged jet-ski damage claims and tuk-tuk tours that stop at shops.', 'Ignore strangers who say a sight is closed and check the official entrance yourself. Use metered taxis or ride-hailing apps, agree on prices first, and photograph rental vehicles before use.', 'https://travel.state.gov/traveladvisories'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM rj_risk_scores WHERE country_id = (SELECT id FROM rj_countries WHERE iso2 = 'TH') AND city_id IS NULL AND risk_type = 'crime_petty');
