-- Place safety tips -----------------------------------------------------------
INSERT INTO rj_place_safety (place_id, risk_type, title, tip)
SELECT (SELECT id FROM rj_places WHERE name_en = 'The Grand Palace and Wat Phra Kaew' LIMIT 1), 'crime_petty', '"Palace is closed" scam', 'Friendly strangers outside claim the palace is closed for a ceremony and offer a tuk-tuk tour that ends at a gem shop. Walk on to the official entrance yourself.'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM rj_place_safety WHERE place_id = (SELECT id FROM rj_places WHERE name_en = 'The Grand Palace and Wat Phra Kaew' LIMIT 1) AND title = '"Palace is closed" scam');
INSERT INTO rj_place_safety (place_id, risk_type, title, tip)
SELECT (SELECT id FROM rj_places WHERE name_en = 'Wat Arun' LIMIT 1), 'natural', 'Steep, narrow steps', 'The prang''s steps are very steep. Use the handrails and avoid climbing in wet sandals.'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM rj_place_safety WHERE place_id = (SELECT id FROM rj_places WHERE name_en = 'Wat Arun' LIMIT 1) AND title = 'Steep, narrow steps');
INSERT INTO rj_place_safety (place_id, risk_type, title, tip)
SELECT (SELECT id FROM rj_places WHERE name_en = 'Railay Beach' LIMIT 1), 'natural', 'Longtail boats stop in rough seas', 'In the monsoon (May–October) boats may not run, and waves can make landings wet and slippery. Check the weather and keep valuables in a dry bag.'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM rj_place_safety WHERE place_id = (SELECT id FROM rj_places WHERE name_en = 'Railay Beach' LIMIT 1) AND title = 'Longtail boats stop in rough seas');
INSERT INTO rj_place_safety (place_id, risk_type, title, tip)
SELECT (SELECT id FROM rj_places WHERE name_en = 'Tiger Cave Temple (Wat Tham Suea)' LIMIT 1), 'health', 'Heat and monkeys', 'The climb is exhausting in the heat. Start before 08:00 and carry water. Monkeys grab bags and food, so keep both closed and out of sight.'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM rj_place_safety WHERE place_id = (SELECT id FROM rj_places WHERE name_en = 'Tiger Cave Temple (Wat Tham Suea)' LIMIT 1) AND title = 'Heat and monkeys');
INSERT INTO rj_place_safety (place_id, risk_type, title, tip)
SELECT (SELECT id FROM rj_places WHERE name_en = 'Phi Phi Islands and Maya Bay' LIMIT 1), 'natural', 'Sea conditions', 'Speedboat trips can be rough. Wear the life jacket and sit towards the back if you get seasick.'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM rj_place_safety WHERE place_id = (SELECT id FROM rj_places WHERE name_en = 'Phi Phi Islands and Maya Bay' LIMIT 1) AND title = 'Sea conditions');
INSERT INTO rj_place_safety (place_id, risk_type, title, tip)
SELECT (SELECT id FROM rj_places WHERE name_en = 'Kew Mae Pan Nature Trail' LIMIT 1), 'natural', 'Cold at dawn', 'Temperatures can drop close to 0 °C before sunrise in December–January. Bring warm layers.'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM rj_place_safety WHERE place_id = (SELECT id FROM rj_places WHERE name_en = 'Kew Mae Pan Nature Trail' LIMIT 1) AND title = 'Cold at dawn');
INSERT INTO rj_place_safety (place_id, risk_type, title, tip)
SELECT (SELECT id FROM rj_places WHERE name_en = 'Fushimi Inari Taisha' LIMIT 1), 'natural', 'Dark, slippery steps at night', 'The upper trail is unlit in places and stone steps get slippery. Bring a light if you hike after sunset.'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM rj_place_safety WHERE place_id = (SELECT id FROM rj_places WHERE name_en = 'Fushimi Inari Taisha' LIMIT 1) AND title = 'Dark, slippery steps at night');
INSERT INTO rj_place_safety (place_id, risk_type, title, tip)
