INSERT INTO rj_visa_rules (nationality_country_id, destination_country_id, visa_type, max_stay_days, fee_text, summary, how_to_apply, official_url, verified_at)
VALUES ((SELECT id FROM rj_countries WHERE iso2 = 'TH'), (SELECT id FROM rj_countries WHERE iso2 = 'KH'), 'visa_free', 14, 'Free', 'ASEAN visa exemption for Thai citizens. Sources differ on the length of stay (14 or 60 days), and land border crossings with Thailand may be closed, so fly in and confirm before travelling.', 'No visa needed. Fly into Siem Reap or Phnom Penh; check the Thai Department of Consular Affairs for the current border situation.', 'https://www.mfa.go.th/', NULL)
